const rev=t=>Number((t&&t.taskRevision)||1);
const cents=x=>Math.round(Number(x)*100);
const amountValid=x=>Number.isFinite(Number(x))&&Math.abs(Number(x))<=1e9&&Math.abs(Number(x)*100-Math.round(Number(x)*100))<.00001;
const difference=t=>Math.abs(cents(t.book)-cents(t.support));
const latest=t=>(t.reviews||[]).filter(r=>r.taskRevision===rev(t)).at(-1);
const signed=t=>t.status==='Signed off'&&(latest(t)||{}).decision==='Approve';
const blockers=(p,t)=>[...(!amountValid(t.book)||!amountValid(t.support)?['Amounts need at most two decimals']:[]),...(difference(t)>cents(t.tolerance)?['Difference exceeds materiality']:[]),...(!String(t.evidence||'').trim()?['Supporting reference missing']:[]),...((p.exceptions||[]).some(e=>e.task===t.id&&e.status==='Open')?['Open exception']:[]),...(t.dependsOn&&!(p.tasks||[]).some(x=>x.id===t.dependsOn&&signed(x))?['Prerequisite needs current sign-off']:[])];
const canReview=(p,t)=>p.status==='Open'&&t.status==='Ready'&&blockers(p,t).length===0;
const masters=(queries.masters&&queries.masters.data)||[];
const cur=name=>((masters.find(m=>m.name===name)||{}).currency)||'';
const open=(data||[]).filter(p=>p.status==='Open').sort((a,b)=>String(a.due).localeCompare(String(b.due)));
const files=open.slice(0,3).map(p=>{const ts=p.tasks||[];const done=ts.filter(signed).length;return {id:p.id,entity:p.entity,currency:cur(p.entity),name:p.name,owner:p.owner,due:p.due,total:ts.length,done:done,pct:ts.length?Math.round(done/ts.length*100):0,blocked:ts.filter(t=>blockers(p,t).length>0).length,ready:ts.filter(t=>canReview(p,t)).length};});
const money=n=>Number(n).toLocaleString('en-US',{minimumFractionDigits:2});
const queue=open.flatMap(p=>(p.tasks||[]).filter(t=>!signed(t)).map(t=>({p:p,t:t}))).sort((a,b)=>String(a.p.due).localeCompare(String(b.p.due))).slice(0,3).map(x=>({title:x.t.title,sub:x.p.entity+' · '+cur(x.p.entity)+' · '+(blockers(x.p,x.t)[0]||x.t.status),book:money(x.t.book),support:money(x.t.support),difference:(difference(x.t)/100).toFixed(2),tolerance:Number(x.t.tolerance).toFixed(2),over:difference(x.t)>cents(x.t.tolerance)}));
return {files:files,queue:queue,openCount:open.length};

const rev=t=>Number((t&&t.taskRevision)||1);
const cents=x=>Math.round(Number(x)*100);
const amountValid=x=>Number.isFinite(Number(x))&&Math.abs(Number(x))<=1e9&&Math.abs(Number(x)*100-Math.round(Number(x)*100))<.00001;
const difference=t=>Math.abs(cents(t.book)-cents(t.support));
const latest=t=>(t.reviews||[]).filter(r=>r.taskRevision===rev(t)).at(-1);
const signed=t=>t.status==='Signed off'&&(latest(t)||{}).decision==='Approve';
const blockers=(p,t)=>[...(!amountValid(t.book)||!amountValid(t.support)?['Amounts need at most two decimals']:[]),...(difference(t)>cents(t.tolerance)?['Difference exceeds materiality']:[]),...(!String(t.evidence||'').trim()?['Supporting reference missing']:[]),...((p.exceptions||[]).some(e=>e.task===t.id&&e.status==='Open')?['Open exception']:[]),...(t.dependsOn&&!(p.tasks||[]).some(x=>x.id===t.dependsOn&&signed(x))?['Prerequisite needs current sign-off']:[])];
const masters=(queries.masters&&queries.masters.data)||[];
const rows=Array.isArray(data)?data:[];
const p=rows[0];
const empty={id:null,entity:'',currency:'',name:'',owner:'',end:'',due:'',status:'',total:0,done:0,blocked:0,openExceptions:0,exceptions:[],history:[]};
if(!p){return empty;}
const ts=p.tasks||[];
const fmt=n=>Number(n).toFixed(2);
const exceptions=(p.exceptions||[]).map(x=>({head:x.title+' · '+x.status,body:x.status==='Resolved'?(x.resolution||''):(x.note||'')}));
const history=(p.history||[]).slice().reverse().map(h=>{const a=h.archive;const at=a?(a.tasks||[]):[];return {event:h.event||'',note:h.note||'',summary:a?('Archived '+at.length+' workpapers · '+at.filter(signed).length+' current reviews'):'',lines:at.map(t=>t.title+' · '+fmt(t.book)+' / '+fmt(t.support)+' · '+((latest(t)||{}).reviewer||'Legacy review')+' · '+(t.evidence||'')).join('  \n')};});
return {id:p.id,entity:p.entity,currency:((masters.find(m=>m.name===p.entity)||{}).currency)||'',name:p.name,owner:p.owner,end:p.end,due:p.due,status:p.status,total:ts.length,done:ts.filter(signed).length,blocked:ts.filter(t=>blockers(p,t).length>0).length,openExceptions:(p.exceptions||[]).filter(x=>x.status==='Open').length,exceptions:exceptions,history:history};
